package com.agilityactioncamera.director;

import com.agilityactioncamera.rig.CameraPose;
import lombok.Getter;

/**
 * Keeps the player in frame by watching where their model actually lands on
 * screen and nudging the focal point towards it.
 * <p>
 * Shots aim at where the path says the player should be. That is wrong
 * whenever an animation carries the model away from its tile (ziplines hang
 * the player metres above the ground) or the path is still being discovered.
 * This closes the loop: an integrating controller with a dead zone, so the
 * composition each shot intends is kept and only real drift is corrected.
 */
public final class AutoFramer
{
	/**
	 * Fraction of the viewport the player may drift from centre before we correct.
	 */
	static final double DEAD_ZONE_VERTICAL = 0.08;
	static final double DEAD_ZONE_HORIZONTAL = 0.22;
	/**
	 * Local units per second of correction for a full-viewport error.
	 */
	static final double GAIN_HEIGHT = 2400;
	static final double GAIN_LATERAL = 1800;
	static final double MAX_HEIGHT = 1600;
	static final double MAX_LATERAL = 900;
	/**
	 * How fast corrections bleed away once the player is back in the comfortable zone.
	 */
	static final double DECAY_PER_SECOND = 0.35;

	@Getter
	private double heightOffset;
	@Getter
	private double lateralOffset;

	public void reset()
	{
		heightOffset = 0;
		lateralOffset = 0;
	}

	/**
	 * @param errorX player's horizontal screen offset from centre, as a fraction of viewport width (+ is right)
	 * @param errorY vertical offset as a fraction of viewport height (+ is below centre)
	 */
	public void update(double errorX, double errorY, double dt)
	{
		double ey = outside(errorY, DEAD_ZONE_VERTICAL);
		double ex = outside(errorX, DEAD_ZONE_HORIZONTAL);

		// Player below centre: move the focal point down, which is a larger height value
		heightOffset = clamp(ey == 0 ? decay(heightOffset, dt) : heightOffset + ey * GAIN_HEIGHT * dt, MAX_HEIGHT);
		lateralOffset = clamp(ex == 0 ? decay(lateralOffset, dt) : lateralOffset + ex * GAIN_LATERAL * dt, MAX_LATERAL);
	}

	/**
	 * Applies the correction to a pose. Lateral moves along the camera's right vector.
	 */
	public CameraPose apply(CameraPose pose)
	{
		double rightX = Math.cos(pose.getYaw());
		double rightY = Math.sin(pose.getYaw());
		return pose
			.withX(pose.getX() + rightX * lateralOffset)
			.withY(pose.getY() + rightY * lateralOffset)
			.withHeight(pose.getHeight() + heightOffset);
	}

	private static double outside(double error, double deadZone)
	{
		if (Math.abs(error) <= deadZone)
		{
			return 0;
		}
		return error - Math.copySign(deadZone, error);
	}

	private static double decay(double value, double dt)
	{
		return value * Math.exp(-DECAY_PER_SECOND * dt);
	}

	private static double clamp(double v, double max)
	{
		return Math.max(-max, Math.min(max, v));
	}
}

package com.agilityactioncamera.director;

import com.agilityactioncamera.detect.ObstacleKind;
import com.agilityactioncamera.detect.Traversal;
import com.agilityactioncamera.rig.CameraPose;
import lombok.Getter;
import lombok.Value;

/**
 * One traversal's worth of camera direction: turns live player position into
 * the pose the current shot wants, and reports cuts between shots.
 */
public final class CinematicSession
{
	@Value
	public static class Frame
	{
		CameraPose pose;
		ShotType shot;
		double u;
		/**
		 * True on the first frame of a new shot, so the rig can hard-cut instead of easing.
		 */
		boolean cut;
	}

	@Getter
	private final Traversal traversal;
	@Getter
	private ShotPlan plan;
	/**
	 * Path length and kind the current plan was made for, to spot when the traversal outgrows it.
	 */
	private double plannedLength;
	private ObstacleKind plannedKind;
	/**
	 * Expected duration, used for walk-style traversals whose path is not known up front.
	 */
	private final long expectedNanos;
	private final long startNanos;
	private int currentIndex = -1;
	private long shotStartNanos;
	private long landedNanos = -1;
	private boolean replanned;

	/**
	 * Whether {@code expectedNanos} was measured, rather than a guess.
	 */
	private final boolean durationKnown;

	public CinematicSession(Traversal traversal, ShotPlan plan, long startNanos, long expectedNanos)
	{
		this(traversal, plan, startNanos, expectedNanos, false);
	}

	public CinematicSession(Traversal traversal, ShotPlan plan, long startNanos, long expectedNanos, boolean durationKnown)
	{
		this.durationKnown = durationKnown;
		this.traversal = traversal;
		this.plan = plan;
		this.plannedLength = traversal.length();
		this.plannedKind = traversal.getKind();
		this.startNanos = startNanos;
		this.expectedNanos = expectedNanos;
	}

	public Frame frame(long nowNanos, double renderX, double renderY)
	{
		double u;
		if (landedNanos >= 0)
		{
			u = 1;
		}
		else if ((traversal.getTrigger() == Traversal.Trigger.WALK_STYLE && !traversal.isLeapRevealed())
			|| traversal.getTrigger() == Traversal.Trigger.PREVIEW)
		{
			// Never reach 1 by time alone; landing does that
			u = Math.min(0.99, (nowNanos - startNanos) / (double) expectedNanos);
		}
		else
		{
			u = traversal.progress(renderX, renderY);
		}
		int index = plan.indexAt(u);
		boolean cut = index != currentIndex && !replanned;
		if (index != currentIndex || replanned)
		{
			currentIndex = index;
			shotStartNanos = nowNanos;
			replanned = false;
		}

		ShotPlan.Entry entry = plan.getEntries().get(index);
		double t = (nowNanos - shotStartNanos) / 1e9;
		ShotContext c = ShotPlanner.context(traversal, entry.getSide(), u, t).toBuilder()
			.subjectX(renderX)
			.subjectY(renderY)
			.build();

		// The first shot eases in from the player's own camera; only later shots hard-cut
		return new Frame(entry.getType().frame(c), entry.getType(), u, cut && currentIndex > 0);
	}

	/**
	 * Whether progress means "how close to the end": true when the destination
	 * is known, or the obstacle's duration has been measured before. Early
	 * hand-back relies on it.
	 */
	public boolean isProgressReliable()
	{
		boolean timeBased = traversal.getTrigger() == Traversal.Trigger.WALK_STYLE && !traversal.isLeapRevealed();
		return traversal.getTrigger() != Traversal.Trigger.PREVIEW && (!timeBased || durationKnown);
	}

	/**
	 * Seconds into the current shot.
	 */
	public double shotSeconds(long nowNanos)
	{
		return (nowNanos - shotStartNanos) / 1e9;
	}

	/**
	 * Whether the traversal has turned out different enough from what the plan
	 * assumed (much longer, or a different kind of obstacle) to plan again.
	 */
	public boolean isOutdated()
	{
		if (landedNanos >= 0)
		{
			return false;
		}
		boolean grew = traversal.length() > plannedLength * 1.5 + 2 * 128;
		return grew || traversal.getKind() != plannedKind;
	}

	/**
	 * Switches to a new plan. The camera eases into it rather than cutting, so
	 * the change reads as a deliberate camera move.
	 */
	public void replan(ShotPlan newPlan)
	{
		plan = newPlan;
		plannedLength = traversal.length();
		plannedKind = traversal.getKind();
		replanned = true;
	}

	/**
	 * The player has arrived; the current shot holds on them briefly before handing back.
	 */
	public void landed(long nowNanos)
	{
		if (landedNanos < 0)
		{
			landedNanos = nowNanos;
		}
	}

	public boolean isLanded()
	{
		return landedNanos >= 0;
	}

	public boolean isHoldOver(long nowNanos, long holdNanos)
	{
		return landedNanos >= 0 && nowNanos - landedNanos >= holdNanos;
	}
}

package com.agilityactioncamera.director;

import com.agilityactioncamera.detect.PathPoint;
import lombok.Builder;
import lombok.Value;

/**
 * Everything a shot needs to frame one moment of a traversal.
 */
@Value
@Builder(toBuilder = true)
public class ShotContext
{
	PathPoint start;
	PathPoint end;
	/**
	 * Unit travel direction, start to end.
	 */
	double dirX;
	double dirY;
	double lengthTiles;
	/**
	 * Positive when the path descends (local height units).
	 */
	double drop;
	/**
	 * Which side of the path the camera works from: +1 right of travel, -1 left.
	 */
	int side;
	/**
	 * Path progress in [0, 1].
	 */
	double u;
	/**
	 * Seconds since this shot started.
	 */
	double t;
	/**
	 * Where the camera should frame the player (chest height).
	 */
	double subjectX;
	double subjectY;
	double subjectHeight;

	/**
	 * Yaw that looks along the direction of travel.
	 */
	public double travelYaw()
	{
		return Math.atan2(-dirX, dirY);
	}
}

package com.agilityactioncamera.director;

import java.util.List;
import lombok.Value;

/**
 * The shots chosen for one traversal, each covering a slice of path progress.
 */
@Value
public class ShotPlan
{
	@Value
	public static class Entry
	{
		ShotType type;
		int side;
		/**
		 * Path progress at which this shot cuts in.
		 */
		double fromU;
		double score;
	}

	List<Entry> entries;

	/**
	 * Index of the shot covering progress {@code u}.
	 */
	public int indexAt(double u)
	{
		int index = 0;
		for (int i = 0; i < entries.size(); i++)
		{
			if (u >= entries.get(i).getFromU())
			{
				index = i;
			}
		}
		return index;
	}
}

package com.agilityactioncamera.director;

import com.agilityactioncamera.detect.ObstacleKind;
import com.agilityactioncamera.detect.PathPoint;
import com.agilityactioncamera.detect.Traversal;
import com.agilityactioncamera.rig.Angles;
import com.agilityactioncamera.rig.CameraPose;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Random;
import java.util.Set;
import lombok.Setter;

/**
 * Picks shots for a traversal. Every enabled shot is tried on both sides of
 * the path and scored on:
 * <ul>
 * <li><b>fit</b>: how well the shot suits the path shape (long, descending, short)</li>
 * <li><b>clearance</b>: sampled line of sight from the estimated camera position to the
 * player, against terrain and the edge of the loaded scene</li>
 * <li><b>variety</b>: a penalty for repeating recent shots</li>
 * <li>a little randomness, so laps don't all look the same</li>
 * </ul>
 */
public final class ShotPlanner
{
	/**
	 * Chest height above the path, in local units (negative is up).
	 */
	public static final double SUBJECT_HEIGHT_OFFSET = -90;

	private static final double[] SAMPLE_US = {0.1, 0.5, 0.9};
	private static final int RAY_STEPS = 10;
	private static final int HISTORY = 3;

	private final Deque<ShotType> history = new ArrayDeque<>();
	private final Random random;
	@Setter
	private ShotStyle style = ShotStyle.ACTION;

	public ShotPlanner(Random random)
	{
		this.random = random;
	}

	/**
	 * @param cutMinTiles split into two shots when the path is at least this long; 0 disables cuts
	 */
	public ShotPlan plan(Traversal traversal, Terrain terrain, Set<ShotType> enabled, int cutMinTiles)
	{
		List<ShotPlan.Entry> entries = new ArrayList<>();
		if (enabled.isEmpty())
		{
			return new ShotPlan(entries);
		}

		boolean cut = cutMinTiles > 0 && traversal.lengthTiles() >= cutMinTiles && enabled.size() > 1;
		if (cut)
		{
			ShotPlan.Entry first = best(traversal, terrain, enabled, 0, 0.5, null);
			ShotPlan.Entry second = best(traversal, terrain, enabled, 0.5, 1, first.getType());
			entries.add(first);
			entries.add(second);
		}
		else
		{
			entries.add(best(traversal, terrain, enabled, 0, 1, null));
		}

		for (ShotPlan.Entry e : entries)
		{
			remember(e.getType());
		}
		return new ShotPlan(entries);
	}

	public void clearHistory()
	{
		history.clear();
	}

	private ShotPlan.Entry best(Traversal traversal, Terrain terrain, Set<ShotType> enabled, double fromU, double toU, ShotType exclude)
	{
		ShotPlan.Entry best = null;
		for (ShotType type : enabled)
		{
			if (type == exclude)
			{
				continue;
			}
			for (int side : new int[]{1, -1})
			{
				double score = score(type, side, traversal, terrain, fromU, toU);
				if (best == null || score > best.getScore())
				{
					best = new ShotPlan.Entry(type, side, fromU, score);
				}
			}
		}
		if (best == null)
		{
			// Only the excluded shot is enabled; reuse it from the other side
			best = new ShotPlan.Entry(exclude, -1, fromU, 0);
		}
		return best;
	}

	double score(ShotType type, int side, Traversal traversal, Terrain terrain, double fromU, double toU)
	{
		ShotContext base = context(traversal, side, 0, 0);
		double score = type.fit(base) + kindBonus(type, traversal.getKind()) + style.bias(type);

		double blocked = 0;
		for (double s : SAMPLE_US)
		{
			double u = fromU + (toU - fromU) * s;
			ShotContext c = context(traversal, side, u, s * 3);
			blocked += occlusion(type.frame(c), c, terrain);
		}
		score -= 1.5 * blocked / SAMPLE_US.length;

		int recency = 0;
		for (ShotType recent : history)
		{
			if (recent == type)
			{
				score -= 0.45 / (1 + recency);
			}
			recency++;
		}

		return score + random.nextDouble() * 0.3;
	}

	/**
	 * How much an obstacle kind favours a shot. Ziplines want to show the whole
	 * line, balances want to sit close behind or beside the player, and so on.
	 */
	static double kindBonus(ShotType type, ObstacleKind kind)
	{
		switch (kind)
		{
			case ZIPLINE:
				switch (type)
				{
					case ESTABLISHING:
						return 0.6;
					case FLYBY:
						return 0.45;
					case TRACKING:
						return 0.2;
					case HERO:
					case ORBIT:
						return -0.5;
					default:
						return 0;
				}
			case SWING:
				return type == ShotType.FLYBY ? 0.45 : type == ShotType.TRACKING ? 0.3 : 0;
			case JUMP:
				return type == ShotType.TRACKING ? 0.3 : type == ShotType.HERO || type == ShotType.CRANE ? 0.2 : 0;
			case BALANCE:
				return type == ShotType.CHASE || type == ShotType.TRACKING ? 0.3 : type == ShotType.HERO ? 0.2 : 0;
			case MONKEYBARS:
				return type == ShotType.TRACKING ? 0.4 : type == ShotType.ORBIT ? 0.2 : 0;
			case CLIMB:
				return type == ShotType.ORBIT || type == ShotType.CRANE ? 0.3 : 0;
			default:
				return 0;
		}
	}

	/**
	 * Builds a context for progress {@code u}, with the subject on the path.
	 */
	public static ShotContext context(Traversal traversal, int side, double u, double t)
	{
		PathPoint at = traversal.pointAt(u);
		return ShotContext.builder()
			.start(traversal.getStart())
			.end(traversal.getEnd())
			.dirX(traversal.dirX())
			.dirY(traversal.dirY())
			.lengthTiles(traversal.lengthTiles())
			.drop(traversal.drop())
			.side(side)
			.u(u)
			.t(t)
			.subjectX(at.getX())
			.subjectY(at.getY())
			.subjectHeight(at.getHeight() + SUBJECT_HEIGHT_OFFSET)
			.build();
	}

	/**
	 * Estimated distance from the focal point to the camera. The client
	 * derives the real one from pitch and zoom; this approximation is only
	 * used for scoring, never for positioning.
	 */
	static double estimatedDistance(double zoom)
	{
		return 1600 - 900 * zoom;
	}

	/**
	 * Fraction in [0, 1] of the line of sight that is under ground or outside the scene.
	 */
	static double occlusion(CameraPose pose, ShotContext c, Terrain terrain)
	{
		double dist = estimatedDistance(pose.getZoom());
		double horizontal = dist * Math.cos(pose.getPitch());
		double camX = pose.getX() - Angles.forwardX(pose.getYaw()) * horizontal;
		double camY = pose.getY() - Angles.forwardY(pose.getYaw()) * horizontal;
		double camH = pose.getHeight() - dist * Math.sin(pose.getPitch());

		int blocked = 0;
		for (int i = 0; i <= RAY_STEPS; i++)
		{
			double t = (double) i / RAY_STEPS;
			double x = camX + (c.getSubjectX() - camX) * t;
			double y = camY + (c.getSubjectY() - camY) * t;
			double h = camH + (c.getSubjectHeight() - camH) * t;
			double ground = terrain.heightAt(x, y);
			// Heights are negative-up: the ray is underground when it's below (greater than) the ground
			if (Double.isNaN(ground) || h > ground - 16)
			{
				blocked++;
			}
		}
		return (double) blocked / (RAY_STEPS + 1);
	}

	private void remember(ShotType type)
	{
		history.addFirst(type);
		while (history.size() > HISTORY)
		{
			history.removeLast();
		}
	}
}

package com.agilityactioncamera.director;

import com.agilityactioncamera.rig.Angles;
import com.agilityactioncamera.rig.CameraPose;
import com.agilityactioncamera.rig.Easing;

/**
 * Overall directing style: which shots are favoured and how tightly they frame.
 */
public enum ShotStyle
{
	/**
	 * Close, low and moving: Hero, Chase and Flyby, tight zoom, handheld feel.
	 */
	ACTION("Action", 0.22, 0.35, true),
	BALANCED("Balanced", 0.08, 0.15, false),
	/**
	 * Wide and composed: shows off the course.
	 */
	SCENIC("Scenic", 0, 0, false);

	private final String displayName;
	/**
	 * Added to every shot's zoom (closer).
	 */
	private final double zoomPush;
	/**
	 * How far every shot's pitch is pulled towards the lowest angle the client allows.
	 */
	private final double lowerPitch;
	private final boolean handheld;

	ShotStyle(String displayName, double zoomPush, double lowerPitch, boolean handheld)
	{
		this.displayName = displayName;
		this.zoomPush = zoomPush;
		this.lowerPitch = lowerPitch;
		this.handheld = handheld;
	}

	/**
	 * Score bias for a shot under this style.
	 */
	double bias(ShotType type)
	{
		switch (this)
		{
			case ACTION:
				switch (type)
				{
					case HERO:
						return 0.35;
					case CHASE:
						return 0.3;
					case FLYBY:
						return 0.2;
					case TRACKING:
						return 0.15;
					case ORBIT:
						return -0.2;
					case ESTABLISHING:
						// Only as a rare change of pace on very long lines
						return -1.1;
					default:
						return 0;
				}
			case SCENIC:
				return type == ShotType.ESTABLISHING ? 0.3 : type == ShotType.ORBIT || type == ShotType.CRANE ? 0.1 : 0;
			default:
				return type == ShotType.ESTABLISHING ? -0.2 : 0;
		}
	}

	/**
	 * Tightens a shot's framing for this style.
	 *
	 * @param t seconds into the shot, for the handheld motion
	 */
	public CameraPose apply(CameraPose pose, double t, boolean shake)
	{
		double pitch = Easing.lerp(pose.getPitch(), Angles.MIN_PITCH, lowerPitch);
		CameraPose styled = pose
			.withZoom(Easing.clamp01(pose.getZoom() + zoomPush))
			.withPitch(Angles.clampPitch(pitch));
		if (handheld && shake)
		{
			styled = styled
				.withYaw(styled.getYaw() + Math.toRadians(1.1) * wobble(t, 0.37, 0.71))
				.withPitch(Angles.clampPitch(styled.getPitch() + Math.toRadians(0.6) * wobble(t, 0.53, 0.97)));
		}
		return styled;
	}

	/**
	 * Smooth pseudo-random motion in [-1, 1]: incommensurate sines never visibly repeat.
	 */
	static double wobble(double t, double f1, double f2)
	{
		double tau = Angles.TAU;
		return 0.6 * Math.sin(tau * f1 * t) + 0.4 * Math.sin(tau * f2 * t + 1.3);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.agilityactioncamera.director;

import com.agilityactioncamera.rig.Angles;
import com.agilityactioncamera.rig.CameraPose;
import static com.agilityactioncamera.rig.Easing.inOutCubic;
import static com.agilityactioncamera.rig.Easing.lerp;
import static com.agilityactioncamera.rig.Easing.smoothstep;

/**
 * The shot library. Each shot is a pure function from the moment of the
 * traversal to an orbit pose (focal point, yaw, pitch, zoom). Everything is
 * computed from live path geometry; nothing is a stored camera position.
 * <p>
 * Yaw offsets are relative to the travel direction: 0 looks along the
 * direction of travel (camera behind the player), 180 looks back at the
 * player from ahead, and +/-90 is a side-on view.
 */
public enum ShotType
{
	/**
	 * Side-on dolly that runs alongside the player with a slight lead.
	 */
	TRACKING("Tracking")
		{
			@Override
			public CameraPose frame(ShotContext c)
			{
				double lead = 128;
				double drift = Math.toRadians(14) * (c.getU() - 0.5);
				return pose(c, c.getSubjectX() + c.getDirX() * lead, c.getSubjectY() + c.getDirY() * lead, c.getSubjectHeight(),
					c.travelYaw() + c.getSide() * (Math.toRadians(90) - drift), Math.toRadians(26), 0.45);
			}

			@Override
			double fit(ShotContext c)
			{
				return 0.4;
			}
		},

	/**
	 * Low over-the-shoulder chase looking down the line of travel.
	 */
	CHASE("Chase")
		{
			@Override
			public CameraPose frame(ShotContext c)
			{
				double lead = 256;
				return pose(c, c.getSubjectX() + c.getDirX() * lead, c.getSubjectY() + c.getDirY() * lead, c.getSubjectHeight(),
					c.travelYaw() + c.getSide() * Math.toRadians(14), Math.toRadians(30), 0.6);
			}

			@Override
			double fit(ShotContext c)
			{
				return c.getLengthTiles() >= 5 ? 0.35 : 0;
			}
		},

	/**
	 * Starts ahead looking back at the oncoming player, then whips round as
	 * they pass, ending behind them. The signature GTA shot.
	 */
	FLYBY("Flyby")
		{
			@Override
			public CameraPose frame(ShotContext c)
			{
				double e = inOutCubic(c.getU());
				double offset = Math.toRadians(lerp(150, 35, e));
				return pose(c, c.getSubjectX(), c.getSubjectY(), c.getSubjectHeight(),
					c.travelYaw() + c.getSide() * offset, Math.toRadians(24), lerp(0.7, 0.4, e));
			}

			@Override
			double fit(ShotContext c)
			{
				return c.getLengthTiles() >= 6 ? 0.55 : 0;
			}
		},

	/**
	 * Crane move: top-down to low for descents, low to top-down for climbs.
	 */
	CRANE("Crane")
		{
			@Override
			public CameraPose frame(ShotContext c)
			{
				double e = smoothstep(c.getU());
				boolean descending = c.getDrop() >= 0;
				double pitch = descending ? lerp(62, 25, e) : lerp(25, 62, e);
				return pose(c, c.getSubjectX(), c.getSubjectY(), c.getSubjectHeight(),
					c.travelYaw() + c.getSide() * Math.toRadians(70), Math.toRadians(pitch), lerp(0.3, 0.55, e));
			}

			@Override
			double fit(ShotContext c)
			{
				return Math.abs(c.getDrop()) > 150 ? 0.6 : 0.1;
			}
		},

	/**
	 * Slow orbit around the player. Good for short or vertical obstacles where the path itself isn't interesting.
	 */
	ORBIT("Orbit")
		{
			@Override
			public CameraPose frame(ShotContext c)
			{
				double yaw = c.travelYaw() + c.getSide() * (Math.toRadians(60) + c.getT() * Math.toRadians(28));
				return pose(c, c.getSubjectX(), c.getSubjectY(), c.getSubjectHeight(), yaw, Math.toRadians(32), 0.55);
			}

			@Override
			double fit(ShotContext c)
			{
				return c.getLengthTiles() < 6 ? 0.5 : 0.1;
			}
		},

	/**
	 * Low, tight front three-quarter angle looking up at the player.
	 */
	HERO("Hero")
		{
			@Override
			public CameraPose frame(ShotContext c)
			{
				return pose(c, c.getSubjectX(), c.getSubjectY(), c.getSubjectHeight() - 60,
					c.travelYaw() + c.getSide() * Math.toRadians(150), Angles.MIN_PITCH, 0.75);
			}

			@Override
			double fit(ShotContext c)
			{
				return 0.25;
			}
		},

	/**
	 * Wide side view of the whole obstacle; the player crosses the frame.
	 * Best for long ziplines and deathslides.
	 */
	ESTABLISHING("Establishing")
		{
			@Override
			public CameraPose frame(ShotContext c)
			{
				double midX = (c.getStart().getX() + c.getEnd().getX()) / 2;
				double midY = (c.getStart().getY() + c.getEnd().getY()) / 2;
				double midH = (c.getStart().getHeight() + c.getEnd().getHeight()) / 2 - 90;
				// Mostly locked off, drifting a little towards the subject so they stay framed
				double follow = 0.3;
				return pose(c,
					lerp(midX, c.getSubjectX(), follow),
					lerp(midY, c.getSubjectY(), follow),
					lerp(midH, c.getSubjectHeight(), follow),
					c.travelYaw() + c.getSide() * Math.toRadians(90), Math.toRadians(38), 0.15);
			}

			@Override
			double fit(ShotContext c)
			{
				return c.getLengthTiles() >= 8 ? 0.6 : -0.5;
			}
		};

	private final String displayName;

	ShotType(String displayName)
	{
		this.displayName = displayName;
	}

	/**
	 * Desired camera pose for this moment of the traversal.
	 */
	public abstract CameraPose frame(ShotContext c);

	/**
	 * How well this shot suits the traversal's shape, before occlusion and variety are considered.
	 */
	abstract double fit(ShotContext c);

	@Override
	public String toString()
	{
		return displayName;
	}

	private static CameraPose pose(ShotContext c, double x, double y, double height, double yaw, double pitch, double zoom)
	{
		return new CameraPose(x, y, height, Angles.wrap(yaw), Angles.clampPitch(pitch), zoom);
	}
}

package com.agilityactioncamera.director;

/**
 * Ground height lookup used to keep cameras out of hills and walls.
 */
@FunctionalInterface
public interface Terrain
{
	/**
	 * Ground height at a local position (negative is up), or {@link Double#NaN}
	 * outside the loaded scene.
	 */
	double heightAt(double x, double y);
}

package com.agilityactioncamera.rig;

/**
 * Angle helpers for the client camera.
 * <p>
 * Since rev 239 the client measures camera angles in JAU14: 16384 units per
 * full turn. Yaw 0 looks north (+y in local coordinates) and the camera's
 * forward vector for yaw {@code a} is {@code (-sin a, cos a)}, as derived from
 * {@code Perspective.localToCanvas}. Positive pitch looks down.
 */
public final class Angles
{
	public static final int JAU_PER_TURN = 16384;
	public static final double TAU = Math.PI * 2;

	/**
	 * Pitch limits the client enforces without the pitch relaxer (128..383 in the old 2048-unit scale).
	 */
	public static final double MIN_PITCH = toRadians(128 * 8);
	public static final double MAX_PITCH = toRadians(383 * 8);

	private Angles()
	{
	}

	public static double toRadians(int jau)
	{
		return jau * TAU / JAU_PER_TURN;
	}

	public static int toJau(double radians)
	{
		int jau = (int) Math.round(radians * JAU_PER_TURN / TAU) % JAU_PER_TURN;
		return jau < 0 ? jau + JAU_PER_TURN : jau;
	}

	/**
	 * Wraps an angle into [-pi, pi).
	 */
	public static double wrap(double radians)
	{
		double a = (radians + Math.PI) % TAU;
		if (a < 0)
		{
			a += TAU;
		}
		return a - Math.PI;
	}

	/**
	 * Yaw that makes the camera look along the horizontal direction (dx, dy).
	 */
	public static double yawLookingAlong(double dx, double dy)
	{
		return Math.atan2(-dx, dy);
	}

	/**
	 * Horizontal unit vector the camera looks along for the given yaw.
	 */
	public static double forwardX(double yaw)
	{
		return -Math.sin(yaw);
	}

	public static double forwardY(double yaw)
	{
		return Math.cos(yaw);
	}

	public static double clampPitch(double pitch)
	{
		return Math.max(MIN_PITCH, Math.min(MAX_PITCH, pitch));
	}
}

package com.agilityactioncamera.rig;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.VarClientID;

/**
 * Owns the client camera while a cinematic plays. Must only be used on the client thread.
 * <p>
 * Lifecycle: {@link #take()} snapshots the player's camera and switches to
 * free camera mode; {@link #drive} applies smoothed poses each frame;
 * {@link #release()} glides back to the player's own camera and then
 * restores the snapshot; {@link #restoreNow()} restores immediately.
 */
@Slf4j
@Singleton
public class CameraController
{
	private static final int FREE_CAMERA = 1;
	private static final int FALLBACK_ZOOM_MIN = 128;
	private static final int FALLBACK_ZOOM_MAX = 1400;
	/**
	 * Close enough to the player's camera to switch back without a visible pop.
	 */
	private static final double RETURN_EPSILON = 6;

	public enum State
	{
		IDLE,
		ACTIVE,
		RETURNING,
	}

	private final Client client;
	private final CameraRig rig = new CameraRig();

	@Getter
	private State state = State.IDLE;
	private Snapshot snapshot;
	private int lastZoomApplied = Integer.MIN_VALUE;
	private long returnStartedNanos;
	private boolean unitsChecked;

	@Inject
	CameraController(Client client)
	{
		this.client = client;
	}

	/**
	 * Whether the camera is currently detached from the player. While true, world interaction must be blocked.
	 */
	public boolean isDetached()
	{
		return state == State.ACTIVE;
	}

	/**
	 * Whether the plugin is moving the camera at all, including the glide back.
	 */
	public boolean isControlling()
	{
		return state != State.IDLE;
	}

	/**
	 * Whether the player is already using the free camera themselves, in which case we don't interfere.
	 */
	public boolean isUserInFreeCamera()
	{
		return state == State.IDLE && client.getCameraMode() == FREE_CAMERA;
	}

	public boolean take()
	{
		if (state == State.ACTIVE)
		{
			return true;
		}
		if (state == State.IDLE)
		{
			if (client.getCameraMode() == FREE_CAMERA)
			{
				return false;
			}
			snapshot = Snapshot.capture(client);
			checkUnits();
			rig.snap(currentPose());
			lastZoomApplied = Integer.MIN_VALUE;
		}
		// Taking over again while returning keeps the original snapshot and the rig's momentum
		state = State.ACTIVE;
		client.setCameraMode(FREE_CAMERA);
		return true;
	}

	/**
	 * Applies one frame of camera motion.
	 *
	 * @param desired the pose the shot wants
	 * @param omega   spring stiffness
	 * @param cut     hard cut straight to {@code desired}
	 */
	public void drive(CameraPose desired, double omega, double dt, boolean cut)
	{
		if (state != State.ACTIVE)
		{
			return;
		}
		if (cut)
		{
			rig.snap(desired);
		}
		apply(cut ? desired : rig.update(desired, omega, dt));
	}

	/**
	 * Hands the camera back: it reattaches to the player at once, so world
	 * clicks work again straight away, and only the angle and zoom glide back
	 * (see {@link #driveReturn}).
	 */
	public void release(long nowNanos)
	{
		if (state == State.ACTIVE)
		{
			state = State.RETURNING;
			returnStartedNanos = nowNanos;
			client.setCameraMode(snapshot.mode);
		}
	}

	/**
	 * Per-frame update while returning; restores the snapshot once the glide completes or times out.
	 */
	public void driveReturn(double playerX, double playerY, double playerHeight, double omega, double dt, long nowNanos, long maxReturnNanos)
	{
		if (state != State.RETURNING)
		{
			return;
		}
		CameraPose home = new CameraPose(playerX, playerY, playerHeight,
			Angles.toRadians(snapshot.yawTarget), Angles.toRadians(snapshot.pitchTarget), normalisedZoom(snapshot.activeZoom()));
		applyAngles(rig.update(home, omega, dt));

		if (rig.distanceTo(home) < RETURN_EPSILON || nowNanos - returnStartedNanos >= maxReturnNanos)
		{
			restoreNow();
		}
	}

	/**
	 * Gives the camera back immediately, e.g. on logout or plugin shutdown.
	 */
	public void restoreNow()
	{
		if (state == State.IDLE)
		{
			return;
		}
		state = State.IDLE;
		client.setCameraMode(snapshot.mode);
		client.setCameraYawTarget(snapshot.yawTarget);
		client.setCameraPitchTarget(snapshot.pitchTarget);
		client.runScript(ScriptID.CAMERA_DO_ZOOM, snapshot.zoomSmall, snapshot.zoomBig);
		snapshot = null;
	}

	public CameraPose currentRigPose()
	{
		return rig.current();
	}

	/**
	 * The yaw target's unit isn't documented; we assume JAU14 like the actual
	 * yaw. Compare against the radian yaw once so a wrong assumption shows up in the log.
	 */
	private void checkUnits()
	{
		if (unitsChecked)
		{
			return;
		}
		unitsChecked = true;
		double target = Angles.toRadians(client.getCameraYawTarget());
		double actual = client.getCameraFpYaw();
		if (Math.abs(Angles.wrap(target - actual)) > 0.3)
		{
			log.warn("Camera yaw target {} doesn't match actual yaw {} rad; angle units may have changed", client.getCameraYawTarget(), actual);
		}
	}

	private CameraPose currentPose()
	{
		return new CameraPose(
			client.getCameraFocalPointX(),
			client.getCameraFocalPointZ(),
			client.getCameraFocalPointY(),
			Angles.toRadians(client.getCameraYawTarget()),
			Angles.toRadians(client.getCameraPitchTarget()),
			normalisedZoom(snapshot.activeZoom()));
	}

	private void apply(CameraPose pose)
	{
		// The client keeps x/z as the horizontal plane and y as height
		client.setCameraFocalPointX((float) pose.getX());
		client.setCameraFocalPointZ((float) pose.getY());
		client.setCameraFocalPointY((float) pose.getHeight());
		applyAngles(pose);
	}

	/**
	 * Angle and zoom only: what the player's own camera controls set, so it is fine on an attached camera.
	 */
	private void applyAngles(CameraPose pose)
	{
		client.setCameraYawTarget(Angles.toJau(pose.getYaw()));
		client.setCameraPitchTarget(Angles.toJau(Angles.clampPitch(pose.getPitch())));

		int zoom = denormalisedZoom(pose.getZoom());
		if (Math.abs(zoom - lastZoomApplied) >= 2)
		{
			lastZoomApplied = zoom;
			if (client.isResized())
			{
				client.runScript(ScriptID.CAMERA_DO_ZOOM, snapshot.zoomSmall, zoom);
			}
			else
			{
				client.runScript(ScriptID.CAMERA_DO_ZOOM, zoom, snapshot.zoomBig);
			}
		}
	}

	private int[] zoomLimits()
	{
		boolean resized = client.isResized();
		int min = client.getVarcIntValue(resized ? VarClientID.CAMERA_ZOOM_BIG_MIN : VarClientID.CAMERA_ZOOM_SMALL_MIN);
		int max = client.getVarcIntValue(resized ? VarClientID.CAMERA_ZOOM_BIG_MAX : VarClientID.CAMERA_ZOOM_SMALL_MAX);
		if (max <= min)
		{
			return new int[]{FALLBACK_ZOOM_MIN, FALLBACK_ZOOM_MAX};
		}
		return new int[]{min, max};
	}

	private double normalisedZoom(int zoom)
	{
		int[] limits = zoomLimits();
		return Easing.clamp01((zoom - limits[0]) / (double) (limits[1] - limits[0]));
	}

	private int denormalisedZoom(double zoom)
	{
		int[] limits = zoomLimits();
		return (int) Math.round(Easing.lerp(limits[0], limits[1], Easing.clamp01(zoom)));
	}

	private static final class Snapshot
	{
		private final boolean resized;
		private int mode;
		private int yawTarget;
		private int pitchTarget;
		private int zoomSmall;
		private int zoomBig;

		private Snapshot(boolean resized)
		{
			this.resized = resized;
		}

		static Snapshot capture(Client client)
		{
			Snapshot s = new Snapshot(client.isResized());
			s.mode = client.getCameraMode();
			s.yawTarget = client.getCameraYawTarget();
			s.pitchTarget = client.getCameraPitchTarget();
			s.zoomSmall = client.getVarcIntValue(VarClientID.CAMERA_ZOOM_SMALL);
			s.zoomBig = client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG);
			log.debug("Camera snapshot: mode={} yaw={} pitch={} zoom={}/{}", s.mode, s.yawTarget, s.pitchTarget, s.zoomSmall, s.zoomBig);
			return s;
		}

		int activeZoom()
		{
			return resized ? zoomBig : zoomSmall;
		}
	}
}

package com.agilityactioncamera.rig;

import lombok.Value;
import lombok.With;

/**
 * An orbit-style camera pose, which is what the client's free camera accepts:
 * a focal point plus yaw/pitch around it and a zoom level.
 * <p>
 * {@code x}/{@code y} are horizontal local coordinates (y is north), and
 * {@code height} uses the client's height convention, where more negative is
 * higher. The client maps these to focal X, Z and Y respectively.
 */
@Value
@With
public class CameraPose
{
	double x;
	double y;
	double height;
	/**
	 * Radians, see {@link Angles}.
	 */
	double yaw;
	/**
	 * Radians, positive looks down.
	 */
	double pitch;
	/**
	 * Normalised zoom in [0, 1]: 0 is the widest the client allows, 1 the closest.
	 */
	double zoom;
}

package com.agilityactioncamera.rig;

/**
 * Smooths a stream of desired poses with one spring per channel. Yaw is
 * unwrapped so the camera always turns the short way round.
 */
public final class CameraRig
{
	private final Spring x = new Spring(0);
	private final Spring y = new Spring(0);
	private final Spring height = new Spring(0);
	private final Spring yaw = new Spring(0);
	private final Spring pitch = new Spring(0);
	private final Spring zoom = new Spring(0);

	public void snap(CameraPose pose)
	{
		x.snap(pose.getX());
		y.snap(pose.getY());
		height.snap(pose.getHeight());
		yaw.snap(pose.getYaw());
		pitch.snap(pose.getPitch());
		zoom.snap(pose.getZoom());
	}

	/**
	 * @param omega position stiffness; angles use slightly softer springs so
	 *              pans lag the subject a little, like a camera operator
	 */
	public CameraPose update(CameraPose target, double omega, double dt)
	{
		double angleOmega = omega * 0.8;
		// Pick the target yaw closest to the current (unwrapped) yaw
		double yawTarget = yaw.get() + Angles.wrap(target.getYaw() - yaw.get());

		return new CameraPose(
			x.update(target.getX(), omega, dt),
			y.update(target.getY(), omega, dt),
			height.update(target.getHeight(), omega, dt),
			yaw.update(yawTarget, angleOmega, dt),
			pitch.update(target.getPitch(), angleOmega, dt),
			zoom.update(target.getZoom(), angleOmega, dt));
	}

	public CameraPose current()
	{
		return new CameraPose(x.get(), y.get(), height.get(), yaw.get(), pitch.get(), zoom.get());
	}

	/**
	 * Rough distance from {@code target}, mixing positions (local units) and
	 * angles (scaled so one radian counts like ~2 tiles).
	 */
	public double distanceTo(CameraPose target)
	{
		double dx = x.get() - target.getX();
		double dy = y.get() - target.getY();
		double dh = height.get() - target.getHeight();
		double da = Angles.wrap(yaw.get() - target.getYaw()) * 256;
		double dp = (pitch.get() - target.getPitch()) * 256;
		double dz = (zoom.get() - target.getZoom()) * 256;
		return Math.sqrt(dx * dx + dy * dy + dh * dh + da * da + dp * dp + dz * dz);
	}
}

package com.agilityactioncamera.rig;

public final class Easing
{
	private Easing()
	{
	}

	public static double clamp01(double t)
	{
		return Math.max(0, Math.min(1, t));
	}

	public static double smoothstep(double t)
	{
		t = clamp01(t);
		return t * t * (3 - 2 * t);
	}

	public static double inOutCubic(double t)
	{
		t = clamp01(t);
		return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
	}

	public static double outCubic(double t)
	{
		t = clamp01(t);
		return 1 - Math.pow(1 - t, 3);
	}

	public static double lerp(double a, double b, double t)
	{
		return a + (b - a) * t;
	}
}

package com.agilityactioncamera.rig;

/**
 * Critically damped spring. Frame-rate independent, never overshoots, and
 * carries velocity across target changes so moving targets look smooth.
 */
public final class Spring
{
	private double value;
	private double velocity;

	public Spring(double value)
	{
		this.value = value;
	}

	/**
	 * Advances the spring towards {@code target}.
	 *
	 * @param omega stiffness (angular frequency); higher is snappier
	 * @param dt    seconds since the last update
	 */
	public double update(double target, double omega, double dt)
	{
		// Exact solution of the critically damped oscillator over dt
		double x = value - target;
		double exp = Math.exp(-omega * dt);
		double temp = (velocity + omega * x) * dt;
		velocity = (velocity - omega * temp) * exp;
		value = target + (x + temp) * exp;
		return value;
	}

	public void snap(double v)
	{
		value = v;
		velocity = 0;
	}

	public double get()
	{
		return value;
	}

	public double getVelocity()
	{
		return velocity;
	}
}

package com.agilityactioncamera.safety;

import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.EnumSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import net.runelite.api.MenuAction;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;

/**
 * Keeps the plugin within Jagex's rules while the camera is detached: no
 * world interaction may happen from a camera that isn't the player's. World
 * clicks are consumed, and camera input from the player can be treated as
 * "give me my camera back".
 * <p>
 * Input listeners only observe; they never consume or inject events.
 */
@Singleton
public class InteractionGuard extends MouseAdapter implements KeyListener, MouseWheelListener
{
	private static final Set<MenuAction> WORLD_ACTIONS = EnumSet.of(
		MenuAction.WALK, MenuAction.SET_HEADING,
		MenuAction.GAME_OBJECT_FIRST_OPTION, MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION,
		MenuAction.GAME_OBJECT_FOURTH_OPTION, MenuAction.GAME_OBJECT_FIFTH_OPTION,
		MenuAction.NPC_FIRST_OPTION, MenuAction.NPC_SECOND_OPTION, MenuAction.NPC_THIRD_OPTION,
		MenuAction.NPC_FOURTH_OPTION, MenuAction.NPC_FIFTH_OPTION,
		MenuAction.PLAYER_FIRST_OPTION, MenuAction.PLAYER_SECOND_OPTION, MenuAction.PLAYER_THIRD_OPTION,
		MenuAction.PLAYER_FOURTH_OPTION, MenuAction.PLAYER_FIFTH_OPTION, MenuAction.PLAYER_SIXTH_OPTION,
		MenuAction.PLAYER_SEVENTH_OPTION, MenuAction.PLAYER_EIGHTH_OPTION,
		MenuAction.GROUND_ITEM_FIRST_OPTION, MenuAction.GROUND_ITEM_SECOND_OPTION, MenuAction.GROUND_ITEM_THIRD_OPTION,
		MenuAction.GROUND_ITEM_FOURTH_OPTION, MenuAction.GROUND_ITEM_FIFTH_OPTION,
		MenuAction.WORLD_ENTITY_FIRST_OPTION, MenuAction.WORLD_ENTITY_SECOND_OPTION, MenuAction.WORLD_ENTITY_THIRD_OPTION,
		MenuAction.WORLD_ENTITY_FOURTH_OPTION, MenuAction.WORLD_ENTITY_FIFTH_OPTION,
		MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, MenuAction.WIDGET_TARGET_ON_NPC, MenuAction.WIDGET_TARGET_ON_PLAYER,
		MenuAction.WIDGET_TARGET_ON_GROUND_ITEM,
		MenuAction.EXAMINE_OBJECT, MenuAction.EXAMINE_NPC, MenuAction.EXAMINE_ITEM_GROUND, MenuAction.EXAMINE_WORLD_ENTITY
	);

	private final ClientThread clientThread;

	/**
	 * Called on the client thread when the player reaches for the camera themselves.
	 */
	@Setter
	private Runnable onTakeover = () ->
	{
	};

	/**
	 * Only react to input while a cinematic owns the camera.
	 */
	@Setter
	private volatile boolean armed;

	@Inject
	InteractionGuard(ClientThread clientThread)
	{
		this.clientThread = clientThread;
	}

	public static boolean isWorldAction(MenuAction action)
	{
		return WORLD_ACTIONS.contains(action);
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (e.getButton() == MouseEvent.BUTTON2)
		{
			takeover();
		}
		return e;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		takeover();
		return e;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_LEFT:
			case KeyEvent.VK_RIGHT:
			case KeyEvent.VK_UP:
			case KeyEvent.VK_DOWN:
				takeover();
				break;
			default:
				break;
		}
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}

	private void takeover()
	{
		if (armed)
		{
			clientThread.invoke(onTakeover);
		}
	}
}

package com.agilityactioncamera.ui;

import com.agilityactioncamera.AgilityActionCameraConfig;
import com.agilityactioncamera.AgilityActionCameraPlugin;
import com.agilityactioncamera.detect.PathPoint;
import com.agilityactioncamera.detect.Traversal;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Developer aid: draws the detected path and the director's state.
 */
public class DebugOverlay extends Overlay
{
	private final Client client;
	private final AgilityActionCameraPlugin plugin;
	private final AgilityActionCameraConfig config;

	@Inject
	DebugOverlay(Client client, AgilityActionCameraPlugin plugin, AgilityActionCameraConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.debugOverlay())
		{
			return null;
		}

		Traversal traversal = plugin.getLastTraversal();
		if (traversal != null)
		{
			List<PathPoint> points = traversal.getPoints();
			g.setStroke(new BasicStroke(2));
			Point prev = null;
			for (int i = 0; i < points.size(); i++)
			{
				PathPoint p = points.get(i);
				Point canvas = Perspective.localToCanvas(client, new LocalPoint((int) p.getX(), (int) p.getY(), client.getTopLevelWorldView()),
					client.getTopLevelWorldView().getPlane(), 0);
				if (canvas == null)
				{
					prev = null;
					continue;
				}
				g.setColor(i == 0 ? Color.GREEN : i == points.size() - 1 ? Color.RED : Color.YELLOW);
				g.fillOval(canvas.getX() - 4, canvas.getY() - 4, 8, 8);
				if (prev != null)
				{
					g.setColor(Color.CYAN);
					g.drawLine(prev.getX(), prev.getY(), canvas.getX(), canvas.getY());
				}
				prev = canvas;
			}
		}

		g.setColor(Color.WHITE);
		int x = client.getViewportXOffset() + 8;
		int y = client.getViewportYOffset() + 20;
		g.drawString("detector: " + plugin.getDetectorStatus(), x, y);
		g.drawString("camera: " + plugin.getCameraStatus(), x, y + 14);
		return null;
	}
}

package com.agilityactioncamera.ui;

import com.agilityactioncamera.AgilityActionCameraConfig;
import com.agilityactioncamera.AgilityActionCameraPlugin;
import com.agilityactioncamera.rig.Easing;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.MultipleGradientPaint;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Point2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Animated letterbox bars and vignette over the 3D viewport. Drawn under
 * widgets so the interface stays usable.
 */
public class LetterboxOverlay extends Overlay
{
	private static final double IN_SECONDS = 0.45;
	private static final double OUT_SECONDS = 0.6;

	private final Client client;
	private final AgilityActionCameraPlugin plugin;
	private final AgilityActionCameraConfig config;

	private double amount;
	private long lastNanos;
	private BufferedImage vignette;

	@Inject
	LetterboxOverlay(Client client, AgilityActionCameraPlugin plugin, AgilityActionCameraConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long now = System.nanoTime();
		double dt = lastNanos == 0 ? 0 : Math.min(0.1, (now - lastNanos) / 1e9);
		lastNanos = now;

		boolean on = plugin.isCinematicPlaying();
		amount = on ? Math.min(1, amount + dt / IN_SECONDS) : Math.max(0, amount - dt / OUT_SECONDS);
		if (amount <= 0)
		{
			return null;
		}

		int x = client.getViewportXOffset();
		int y = client.getViewportYOffset();
		int w = client.getViewportWidth();
		int h = client.getViewportHeight();
		double e = Easing.inOutCubic(amount);

		if (config.vignette())
		{
			drawVignette(g, x, y, w, h, (float) e);
		}

		if (config.letterbox())
		{
			int bar = (int) Math.round(h * config.letterboxSize() / 100.0 * e);
			g.setColor(Color.BLACK);
			g.fillRect(x, y, w, bar);
			g.fillRect(x, y + h - bar, w, bar);

			String name = plugin.getCurrentShotName();
			if (config.shotName() && name != null && bar > 14)
			{
				g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				Font font = FontManager.getRunescapeSmallFont();
				g.setFont(font);
				FontMetrics fm = g.getFontMetrics();
				g.setColor(new Color(255, 255, 255, (int) (160 * e)));
				g.drawString(name.toUpperCase(), x + w - fm.stringWidth(name.toUpperCase()) - 12, y + h - (bar - fm.getAscent()) / 2 - 2);
			}
		}
		return null;
	}

	private void drawVignette(Graphics2D g, int x, int y, int w, int h, float alpha)
	{
		if (vignette == null || vignette.getWidth() != w || vignette.getHeight() != h)
		{
			vignette = buildVignette(w, h);
		}
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		g.drawImage(vignette, x, y, null);
		g.setComposite(old);
	}

	private static BufferedImage buildVignette(int w, int h)
	{
		BufferedImage img = new BufferedImage(Math.max(1, w), Math.max(1, h), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		float radius = (float) Math.hypot(w, h) / 2f;
		g.setPaint(new RadialGradientPaint(
			new Point2D.Float(w / 2f, h / 2f), radius,
			new float[]{0f, 0.55f, 1f},
			new Color[]{new Color(0, 0, 0, 0), new Color(0, 0, 0, 0), new Color(0, 0, 0, 150)},
			MultipleGradientPaint.CycleMethod.NO_CYCLE));
		g.fillRect(0, 0, w, h);
		g.dispose();
		return img;
	}
}

