package com.agilityactioncamera.detect;

import com.agilityactioncamera.detect.TraversalDetector.Transition;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ObjectID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class TraversalDetectorTest
{
	private static final int IDLE = 808;
	private static final int WALK = 819;
	private static final int RUN = 824;
	private static final int BALANCE_POSE = 762;
	private static final int JUMP = 2586;

	private TraversalDetector detector;
	private int tick;

	@Before
	public void before()
	{
		detector = new TraversalDetector();
		tick = 100;
	}

	@Test
	public void deathslideIsDetectedAndEnds()
	{
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", tick);

		// Walking up to the slide: render lags the server by a tile or two
		assertEquals(Transition.NONE, detector.onTick(sample(0, 0, 1, 0, -1, RUN)));
		assertEquals(Transition.NONE, detector.onTick(sample(1, 0, 2, 0, -1, RUN)));

		// Forced movement: server jumps 12 tiles ahead, model still at the start
		assertEquals(Transition.STARTED, detector.onTick(sample(2, 0, 14, 0, AnimationID.ZIPLINE_SLIDE, IDLE)));
		Traversal t = detector.getCurrent();
		assertEquals(Traversal.Trigger.LEAP, t.getTrigger());
		assertEquals(12, t.lengthTiles(), 1e-9);

		// Sliding along
		assertEquals(Transition.NONE, detector.onTick(sample(6, 0, 14, 0, AnimationID.ZIPLINE_SLIDE, IDLE)));
		assertEquals(Transition.NONE, detector.onTick(sample(11, 0, 14, 0, AnimationID.ZIPLINE_SLIDE, IDLE)));
		assertEquals(0.75, t.progress(11 * 128, 0), 1e-9);

		// Landed; it only counts once the player has stood still for a moment
		assertEquals(Transition.NONE, detector.onTick(sample(14, 0, 14, 0, -1, IDLE)));
		assertEquals(Transition.NONE, detector.onTick(sample(14, 0, 14, 0, -1, IDLE)));
		assertEquals(Transition.ENDED, detector.onTick(sample(14, 0, 14, 0, -1, IDLE)));
		assertFalse(detector.isLastEndAborted());
		assertFalse(detector.isTraversing());
		// Started on tick 102 and landed on 105, not when the detector noticed on 107
		assertEquals(3, detector.getLandingTick() - t.getStartTick());
	}

	@Test
	public void ordinaryRunningIsIgnored()
	{
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", tick);
		for (int i = 0; i < 10; i++)
		{
			assertEquals(Transition.NONE, detector.onTick(sample(i * 2, 0, i * 2 + 2, 0, -1, RUN)));
		}
	}

	@Test
	public void unknownObjectsNeedAnAgilityVerb()
	{
		detector.onObjectClicked(1, "Open", tick);
		assertEquals(Transition.NONE, detector.onTick(sample(0, 0, 10, 0, JUMP, IDLE)));

		detector.onObjectClicked(1, "Jump", tick);
		assertEquals(Transition.STARTED, detector.onTick(sample(0, 0, 10, 0, JUMP, IDLE)));
	}

	@Test
	public void genericDetectionCanBeDisabled()
	{
		detector.setGenericDetection(false);
		detector.onObjectClicked(1, "Jump", tick);
		assertEquals(Transition.NONE, detector.onTick(sample(0, 0, 10, 0, JUMP, IDLE)));
	}

	@Test
	public void armingExpires()
	{
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", tick);
		tick += TraversalDetector.ARM_TIMEOUT_TICKS + 1;
		assertEquals(Transition.NONE, detector.onTick(sample(0, 0, 12, 0, AnimationID.ZIPLINE_SLIDE, IDLE)));
	}

	@Test
	public void walkingAwayDisarms()
	{
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", tick);
		detector.onOtherAction();
		// A generic animation with a big gap is only an obstacle if the player asked for one
		assertEquals(Transition.NONE, detector.onTick(sample(0, 0, 12, 0, JUMP, IDLE)));
	}

	@Test
	public void walkStyleObstacleGrowsItsPath()
	{
		detector.onObjectClicked(ObjectID.GNOME_LOG_BALANCE1, "Walk-across", tick);
		assertEquals(Transition.NONE, detector.onTick(sample(0, 0, 1, 0, -1, BALANCE_POSE)));
		assertEquals(Transition.STARTED, detector.onTick(sample(0.5, 0, 1.5, 0, -1, BALANCE_POSE)));
		assertEquals(Traversal.Trigger.WALK_STYLE, detector.getCurrent().getTrigger());

		for (int x = 2; x <= 7; x++)
		{
			assertEquals(Transition.EXTENDED, detector.onTick(sample(x - 1, 0, x, 0, -1, BALANCE_POSE)));
		}
		assertEquals(Transition.NONE, detector.onTick(sample(7, 0, 7, 0, -1, IDLE)));
		assertEquals(Transition.NONE, detector.onTick(sample(7, 0, 7, 0, -1, IDLE)));
		assertEquals(Transition.ENDED, detector.onTick(sample(7, 0, 7, 0, -1, IDLE)));
		assertEquals(7, detector.getCurrent().getEnd().getX() / 128, 1e-9);
	}

	/**
	 * What the Colossal Wyrm zipline looked like in-game: it starts as a short
	 * walk onto the platform, then the server tile leaps to the far end.
	 */
	@Test
	public void ziplineThatStartsWithAWalkOnRevealsItsLeap()
	{
		int zipline = ObjectID.VARLAMORE_WYRM_AGILITY_END_ZIPLINE_TRIGGER;
		detector.onObjectClicked(zipline, "Grab", tick);
		detector.onTick(sample(0, 0, 1, 0, -1, AnimationID.WYRM_AGILITY_ZIPLINE_WALK));
		assertEquals(Transition.STARTED, detector.onTick(sample(0.3, 0, 1.7, 0, -1, AnimationID.WYRM_AGILITY_ZIPLINE_WALK)));
		Traversal t = detector.getCurrent();
		assertEquals(ObstacleKind.ZIPLINE, t.getKind());
		assertFalse(t.isLeapRevealed());

		assertEquals(Transition.EXTENDED, detector.onTick(sample(1.6, 0, 16, 0, AnimationID.WYRM_AGILITY_ZIPLINE_ON, IDLE)));
		assertTrue(t.isLeapRevealed());
		assertEquals(15.7, t.lengthTiles(), 0.01);
	}

	@Test
	public void unknownObstacleKindComesFromTheAnimation()
	{
		detector.onObjectClicked(1, "Swing-on", tick);
		detector.onTick(sample(0, 0, 8, 0, AnimationID.HUMAN_ROPESWING_LONG, IDLE));
		assertEquals(ObstacleKind.SWING, detector.getCurrent().getKind());
	}

	@Test
	public void profileSetsTheStartingKindAndMovementRefinesIt()
	{
		detector.onObjectClicked(ObjectID.VARLAMORE_WYRM_AGILITY_ADVANCED_JUMP_1_TRIGGER, "Jump", tick);
		detector.onTick(sample(0, 0, 5, 0, 2586, IDLE));
		Traversal t = detector.getCurrent();
		assertEquals(ObstacleKind.JUMP, t.getKind());

		// Reaching for a ladder doesn't override a profile
		detector.onTick(sample(1, 0, 5, 0, AnimationID.HUMAN_REACHFORLADDER, IDLE));
		assertEquals(ObstacleKind.JUMP, t.getKind());

		// A chained balance without a new click does
		detector.onTick(sample(2, 0, 5, 0, AnimationID.WYRM_AGILITY_TIGHTROPE_WOBBLE, IDLE));
		assertEquals(ObstacleKind.BALANCE, t.getKind());
	}

	/**
	 * Courses are run without stopping: running on to the next obstacle ends
	 * the traversal and doesn't stretch its path.
	 */
	@Test
	public void runningOnEndsTheTraversal()
	{
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", tick);
		detector.onTick(sample(0, 0, 12, 0, AnimationID.ZIPLINE_SLIDE, IDLE));
		Traversal t = detector.getCurrent();
		detector.onTick(sample(12, 0, 12, 0, AnimationID.ZIPLINE_SLIDE, IDLE));
		// Landed and running straight on, render a couple of tiles behind the server
		assertNotEquals(Transition.ENDED, detector.onTick(sample(12, 0, 14, 0, -1, RUN)));
		assertNotEquals(Transition.ENDED, detector.onTick(sample(14, 0, 16, 0, -1, RUN)));
		assertEquals(Transition.ENDED, detector.onTick(sample(16, 0, 18, 0, -1, RUN)));
		assertEquals("running isn't part of the path", 12, t.lengthTiles(), 1e-9);
	}

	@Test
	public void wyrmMonkeybarsAreKnown()
	{
		assertTrue(ObstacleCatalog.isCourseObstacle(ObjectID.VARLAMORE_WYRM_AGILITY_ADVANCED_MONKEYBARS_1_TRIGGER));
		assertTrue(ObstacleCatalog.isCourseObstacle(ObjectID.VARLAMORE_WYRM_AGILITY_MULTIJUMP_TERMITES));
	}

	/**
	 * Replays the Colossal Wyrm advanced tightrope from a real detection log.
	 * The obstacle swaps the player's walk animation to the balance walk, so
	 * the pose "matches the walk" the whole way across; only comparing against
	 * the player's own remembered poses reveals it. It ends in a ledge drop,
	 * which must stay part of the same traversal.
	 */
	@Test
	public void wyrmTightropeFromRealLog()
	{
		int balanceWalk = 762;
		int balanceIdle = 763;
		int wobble = AnimationID.WYRM_AGILITY_TIGHTROPE_WOBBLE;

		// Standing around normally first, so the detector learns the player's own poses
		for (int i = 0; i < 6; i++)
		{
			detector.onTick(pose(43, 27, 43, 27, -1, IDLE, WALK));
		}
		detector.onObjectClicked(ObjectID.VARLAMORE_WYRM_AGILITY_ADVANCED_BALANCE_1_TRIGGER, "Cross", tick);

		// Walking to the rope
		assertEquals(Transition.NONE, detector.onTick(pose(43, 27, 42, 28, -1, WALK, WALK)));
		assertEquals(Transition.NONE, detector.onTick(pose(42, 28, 41, 28, -1, WALK, WALK)));
		// On the rope: walk animation swapped to the balance walk
		assertEquals(Transition.NONE, detector.onTick(pose(41, 28, 40, 29, -1, balanceWalk, balanceWalk)));
		assertEquals(Transition.STARTED, detector.onTick(pose(40, 29, 39, 30, -1, balanceWalk, balanceWalk)));
		Traversal t = detector.getCurrent();
		assertEquals(ObstacleKind.BALANCE, t.getKind());

		detector.onTick(pose(39, 30, 38, 31, -1, balanceWalk, balanceWalk));
		// Wobbling in place for a few ticks must not end it
		for (int i = 0; i < 4; i++)
		{
			assertNotEquals(Transition.ENDED, detector.onTick(pose(38, 31, 38, 31, wobble, balanceIdle, balanceWalk)));
		}
		detector.onTick(pose(38, 31, 37, 32, -1, balanceIdle, balanceWalk));
		detector.onTick(pose(37, 32, 36, 33, -1, balanceWalk, balanceWalk));
		detector.onTick(pose(36, 33, 35, 34, -1, balanceWalk, balanceWalk));
		// Off the rope, a one-tick pause, then the ledge drop
		assertNotEquals(Transition.ENDED, detector.onTick(pose(35, 34, 35, 34, -1, WALK, WALK)));
		assertNotEquals(Transition.ENDED, detector.onTick(pose(35, 34, 35, 34, -1, IDLE, WALK)));
		assertNotEquals(Transition.ENDED, detector.onTick(pose(35, 34, 34, 36, 1995, 823, WALK)));
		detector.onTick(pose(34, 35, 34, 36, 1995, 823, WALK));
		detector.onTick(pose(34, 36, 34, 36, -1, IDLE, WALK));
		detector.onTick(pose(34, 36, 34, 36, -1, IDLE, WALK));
		assertEquals(Transition.ENDED, detector.onTick(pose(34, 36, 34, 36, -1, IDLE, WALK)));

		assertTrue("one traversal covering rope and ledge: " + t.lengthTiles(), t.lengthTiles() > 8);
	}

	/**
	 * One click, several movements: the tightrope after a chained jump must be
	 * picked up from its animation alone.
	 */
	@Test
	public void chainedObstacleNeedsNoClick()
	{
		for (int i = 0; i < 6; i++)
		{
			detector.onTick(pose(0, 0, 0, 0, -1, IDLE, WALK));
		}
		assertEquals(Transition.NONE, detector.onTick(pose(0, 0, 1, 0, -1, 762, 762)));
		assertEquals(Transition.STARTED, detector.onTick(pose(0.5, 0, 2, 0, -1, 762, 762)));
		assertEquals(-1, detector.getCurrent().getObjectId());
		assertEquals(ObstacleKind.BALANCE, detector.getCurrent().getKind());
	}

	@Test
	public void clickFreeDetectionCanBeDisabled()
	{
		detector.setClickFree(false);
		for (int i = 0; i < 6; i++)
		{
			detector.onTick(pose(0, 0, 0, 0, -1, IDLE, WALK));
		}
		detector.onTick(pose(0, 0, 1, 0, -1, 762, 762));
		assertEquals(Transition.NONE, detector.onTick(pose(0.5, 0, 2, 0, -1, 762, 762)));
	}

	@Test
	public void turningOnTheSpotIsOrdinary()
	{
		for (int i = 0; i < 6; i++)
		{
			detector.onTick(pose(0, 0, 0, 0, -1, IDLE, WALK));
		}
		assertTrue(detector.isOrdinary(pose(0, 0, 1, 0, -1, AnimationID.HUMAN_TURNONSPOT, WALK)));
		assertTrue(detector.isOrdinary(pose(0, 0, 1, 0, -1, AnimationID.HUMAN_WALK_L, WALK)));
	}

	@Test
	public void obstacleWalkIsNotLearnedAsTheNormalWalk()
	{
		for (int i = 0; i < 6; i++)
		{
			detector.onTick(pose(0, 0, 0, 0, -1, IDLE, WALK));
		}
		// Right after an obstacle the game can still have the balance walk active
		detector.onTick(pose(0, 0, 0, 0, -1, 762, 762));
		PlayerSample balancing = pose(0, 0, 1, 0, -1, 762, 762);
		assertFalse(detector.isOrdinary(balancing));
	}

	@Test
	public void teleportAborts()
	{
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", tick);
		detector.onTick(sample(0, 0, 12, 0, AnimationID.ZIPLINE_SLIDE, IDLE));
		assertTrue(detector.isTraversing());
		assertEquals(Transition.ENDED, detector.onTick(sample(60, 60, 60, 60, -1, IDLE)));
		assertTrue(detector.isLastEndAborted());
	}

	@Test
	public void timesOut()
	{
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", tick);
		detector.onTick(sample(0, 0, 12, 0, AnimationID.ZIPLINE_SLIDE, IDLE));
		tick += TraversalDetector.TRAVERSAL_TIMEOUT_TICKS + 1;
		assertEquals(Transition.ENDED, detector.onTick(sample(1, 0, 12, 0, AnimationID.ZIPLINE_SLIDE, IDLE)));
		assertTrue(detector.isLastEndAborted());
	}

	/**
	 * Like {@link #sample} but with the current walk animation, which obstacles swap out.
	 */
	private PlayerSample pose(double renderX, double renderY, double serverX, double serverY, int animation, int pose, int walk)
	{
		return PlayerSample.builder()
			.tick(tick++)
			.renderX((int) Math.round(renderX * 128))
			.renderY((int) Math.round(renderY * 128))
			.serverX((int) Math.round(serverX * 128))
			.serverY((int) Math.round(serverY * 128))
			.animation(animation)
			.poseAnimation(pose)
			.idlePose(walk == WALK ? IDLE : 763)
			.walkPose(walk)
			.runPose(walk == WALK ? RUN : walk)
			.build();
	}

	/**
	 * Positions in tiles; advances the tick.
	 */
	private PlayerSample sample(double renderX, double renderY, double serverX, double serverY, int animation, int pose)
	{
		return PlayerSample.builder()
			.tick(tick++)
			.renderX((int) Math.round(renderX * 128))
			.renderY((int) Math.round(renderY * 128))
			.serverX((int) Math.round(serverX * 128))
			.serverY((int) Math.round(serverY * 128))
			.animation(animation)
			.poseAnimation(pose)
			.idlePose(IDLE)
			.walkPose(WALK)
			.runPose(RUN)
			.build();
	}
}

package com.agilityactioncamera.director;

import com.agilityactioncamera.rig.CameraPose;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AutoFramerTest
{
	@Test
	public void leavesComposedShotsAloneInsideTheDeadZone()
	{
		AutoFramer framer = new AutoFramer();
		for (int i = 0; i < 60; i++)
		{
			framer.update(0.15, 0.05, 1 / 60.0);
		}
		assertEquals(0, framer.getHeightOffset(), 1e-9);
		assertEquals(0, framer.getLateralOffset(), 1e-9);
	}

	@Test
	public void playerAboveFrameRaisesTheFocalPoint()
	{
		// e.g. hanging from a zipline well above the path
		AutoFramer framer = new AutoFramer();
		for (int i = 0; i < 30; i++)
		{
			framer.update(0, -0.4, 1 / 60.0);
		}
		// Negative is up
		assertTrue(framer.getHeightOffset() < -100);
	}

	@Test
	public void lateralCorrectionFollowsTheCameraRightVector()
	{
		AutoFramer framer = new AutoFramer();
		for (int i = 0; i < 30; i++)
		{
			framer.update(0.45, 0, 1 / 60.0);
		}
		// Camera looking north: screen-right is east (+x)
		CameraPose p = framer.apply(new CameraPose(0, 0, 0, 0, 0.5, 0.5));
		assertTrue(p.getX() > 50);
		assertEquals(0, p.getY(), 1e-6);
	}

	@Test
	public void correctionsAreBoundedAndDecay()
	{
		AutoFramer framer = new AutoFramer();
		for (int i = 0; i < 600; i++)
		{
			framer.update(0, 0.5, 1 / 60.0);
		}
		assertEquals(AutoFramer.MAX_HEIGHT, framer.getHeightOffset(), 1e-9);

		for (int i = 0; i < 600; i++)
		{
			framer.update(0, 0, 1 / 60.0);
		}
		assertTrue(framer.getHeightOffset() < AutoFramer.MAX_HEIGHT * 0.1);
	}
}

package com.agilityactioncamera.director;

import com.agilityactioncamera.detect.ObstacleKind;
import com.agilityactioncamera.detect.PlayerSample;
import com.agilityactioncamera.detect.Traversal;
import com.agilityactioncamera.detect.TraversalDetector;
import com.agilityactioncamera.rig.Angles;
import com.agilityactioncamera.rig.CameraPose;
import java.util.EnumSet;
import java.util.Random;
import java.util.Set;
import net.runelite.api.gameval.ObjectID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ShotPlannerTest
{
	private static final Terrain FLAT = (x, y) -> 0;
	private static final Set<ShotType> ALL = EnumSet.allOf(ShotType.class);

	@Test
	public void everyShotStaysWithinClientLimits()
	{
		Traversal t = traversal(12);
		for (ShotType type : ShotType.values())
		{
			for (int side : new int[]{1, -1})
			{
				for (double u = 0; u <= 1; u += 0.1)
				{
					CameraPose p = type.frame(ShotPlanner.context(t, side, u, u * 4));
					assertTrue(type + " pitch", p.getPitch() >= Angles.MIN_PITCH - 1e-9 && p.getPitch() <= Angles.MAX_PITCH + 1e-9);
					assertTrue(type + " zoom", p.getZoom() >= 0 && p.getZoom() <= 1);
					assertTrue(type + " yaw", p.getYaw() >= -Math.PI && p.getYaw() < Math.PI);
				}
			}
		}
	}

	@Test
	public void sideShotLooksAcrossThePath()
	{
		// Travelling east; camera on the right (south) side must look north
		Traversal t = traversal(12);
		CameraPose p = ShotType.TRACKING.frame(ShotPlanner.context(t, 1, 0.5, 0));
		assertTrue(Angles.forwardY(p.getYaw()) > 0.9);
	}

	@Test
	public void flybyStartsAheadAndEndsBehind()
	{
		Traversal t = traversal(12);
		CameraPose start = ShotType.FLYBY.frame(ShotPlanner.context(t, 1, 0, 0));
		CameraPose end = ShotType.FLYBY.frame(ShotPlanner.context(t, 1, 1, 0));
		// Looking back (west) at the start, forward (east) at the end
		assertTrue(Angles.forwardX(start.getYaw()) < -0.5);
		assertTrue(Angles.forwardX(end.getYaw()) > 0.5);
	}

	@Test
	public void occlusionPrefersTheOpenSide()
	{
		Traversal t = traversal(12);
		// A cliff along the south side of the path (heights are negative-up)
		Terrain cliff = (x, y) -> y < -128 ? -2000 : 0;
		ShotPlanner planner = new ShotPlanner(new Random(1));

		double right = planner.score(ShotType.TRACKING, 1, t, cliff, 0, 1);
		double left = planner.score(ShotType.TRACKING, -1, t, cliff, 0, 1);
		assertTrue("camera on the open north side should win: left " + left + " right " + right, left > right);
	}

	@Test
	public void sceneEdgeCountsAsBlocked()
	{
		Traversal t = traversal(12);
		CameraPose pose = ShotType.TRACKING.frame(ShotPlanner.context(t, 1, 0.5, 0));
		ShotContext c = ShotPlanner.context(t, 1, 0.5, 0);
		assertEquals(0, ShotPlanner.occlusion(pose, c, FLAT), 1e-9);
		assertEquals(1, ShotPlanner.occlusion(pose, c, (x, y) -> Double.NaN), 1e-9);
	}

	@Test
	public void longObstaclesCutToADifferentShot()
	{
		ShotPlanner planner = new ShotPlanner(new Random(7));
		ShotPlan plan = planner.plan(traversal(14), FLAT, ALL, 10);
		assertEquals(2, plan.getEntries().size());
		assertNotEquals(plan.getEntries().get(0).getType(), plan.getEntries().get(1).getType());
		assertEquals(0, plan.indexAt(0.3));
		assertEquals(1, plan.indexAt(0.7));

		assertEquals(1, planner.plan(traversal(6), FLAT, ALL, 10).getEntries().size());
		assertEquals(1, planner.plan(traversal(14), FLAT, ALL, 0).getEntries().size());
	}

	@Test
	public void varietyAvoidsRepeatingTheSameShot()
	{
		ShotPlanner planner = new ShotPlanner(new Random(3));
		int repeats = 0;
		ShotType last = null;
		for (int i = 0; i < 40; i++)
		{
			ShotType type = planner.plan(traversal(9), FLAT, ALL, 0).getEntries().get(0).getType();
			if (type == last)
			{
				repeats++;
			}
			last = type;
		}
		assertTrue("repeats " + repeats, repeats < 10);
	}

	@Test
	public void respectsEnabledShots()
	{
		ShotPlanner planner = new ShotPlanner(new Random(5));
		ShotPlan plan = planner.plan(traversal(14), FLAT, EnumSet.of(ShotType.ORBIT), 10);
		assertTrue(plan.getEntries().stream().allMatch(e -> e.getType() == ShotType.ORBIT));
		assertTrue(planner.plan(traversal(14), FLAT, EnumSet.noneOf(ShotType.class), 10).getEntries().isEmpty());
	}

	@Test
	public void sessionReportsCutsOnlyBetweenShots()
	{
		Traversal t = traversal(14);
		ShotPlan plan = new ShotPlanner(new Random(7)).plan(t, FLAT, ALL, 10);
		CinematicSession session = new CinematicSession(t, plan, 0, 1);

		assertFalse("first shot eases in", session.frame(0, 0, 0).isCut());
		assertFalse(session.frame(1, 3 * 128, 0).isCut());
		assertTrue("cut at halfway", session.frame(2, 8 * 128, 0).isCut());
		assertFalse(session.frame(3, 9 * 128, 0).isCut());

		session.landed(4);
		assertEquals(1, session.frame(5, 14 * 128, 0).getU(), 1e-9);
		assertTrue(session.isHoldOver(10, 5));
	}

	@Test
	public void scenicZiplinesFavourShotsThatShowTheWholeLine()
	{
		assertTrue(ShotPlanner.kindBonus(ShotType.ESTABLISHING, ObstacleKind.ZIPLINE) > ShotPlanner.kindBonus(ShotType.HERO, ObstacleKind.ZIPLINE));

		int wide = 0;
		ShotPlanner planner = new ShotPlanner(new Random(11));
		planner.setStyle(ShotStyle.SCENIC);
		for (int i = 0; i < 20; i++)
		{
			ShotType type = planner.plan(zipline(14), FLAT, ALL, 0).getEntries().get(0).getType();
			if (type == ShotType.ESTABLISHING || type == ShotType.FLYBY || type == ShotType.TRACKING)
			{
				wide++;
			}
		}
		assertTrue("wide shots " + wide, wide >= 18);
	}

	@Test
	public void actionStyleMostlyAvoidsWideShots()
	{
		ShotPlanner planner = new ShotPlanner(new Random(13));
		planner.setStyle(ShotStyle.ACTION);
		int establishing = 0;
		for (int i = 0; i < 40; i++)
		{
			for (ShotPlan.Entry e : planner.plan(traversal(12), FLAT, ALL, 8).getEntries())
			{
				if (e.getType() == ShotType.ESTABLISHING)
				{
					establishing++;
				}
			}
		}
		assertTrue("establishing " + establishing, establishing <= 4);
	}

	@Test
	public void actionStyleFramesTighterAndLower()
	{
		CameraPose base = new CameraPose(0, 0, 0, 0, Math.toRadians(40), 0.4);
		CameraPose action = ShotStyle.ACTION.apply(base, 0, false);
		assertTrue(action.getZoom() > base.getZoom());
		assertTrue(action.getPitch() < base.getPitch());
		assertEquals(base.getYaw(), action.getYaw(), 1e-9);

		// Handheld shake is small and smooth
		CameraPose a = ShotStyle.ACTION.apply(base, 1.0, true);
		CameraPose b = ShotStyle.ACTION.apply(base, 1.0 + 1 / 60.0, true);
		assertTrue(Math.abs(a.getYaw()) <= Math.toRadians(1.2));
		assertTrue(Math.abs(a.getYaw() - b.getYaw()) < Math.toRadians(0.1));
	}

	@Test
	public void sessionReplansWithoutCuttingWhenThePathGrows()
	{
		TraversalDetector detector = new TraversalDetector();
		detector.onObjectClicked(ObjectID.VARLAMORE_WYRM_AGILITY_END_ZIPLINE_TRIGGER, "Grab", 0);
		int walkOn = 11649;
		detector.onTick(PlayerSample.builder().tick(1).serverX(128).poseAnimation(walkOn).idlePose(808).animation(-1).build());
		detector.onTick(PlayerSample.builder().tick(2).renderX(40).serverX(220).poseAnimation(walkOn).idlePose(808).animation(-1).build());
		Traversal t = detector.getCurrent();
		ShotPlanner planner = new ShotPlanner(new Random(2));
		CinematicSession session = new CinematicSession(t, planner.plan(t, FLAT, ALL, 0), 0, 1);
		session.frame(0, 40, 0);
		assertFalse(session.isOutdated());

		detector.onTick(PlayerSample.builder().tick(3).renderX(200).serverX(16 * 128).poseAnimation(-1).idlePose(808).animation(11650).build());
		assertTrue(session.isOutdated());
		session.replan(planner.plan(t, FLAT, ALL, 0));
		assertFalse(session.isOutdated());
		assertFalse("replans ease, never cut", session.frame(1, 300, 0).isCut());
	}

	private static Traversal zipline(int tiles)
	{
		TraversalDetector detector = new TraversalDetector();
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", 0);
		detector.onTick(PlayerSample.builder()
			.tick(1)
			.serverX(tiles * 128)
			.animation(1602)
			.poseAnimation(-1)
			.idlePose(808)
			.build());
		return detector.getCurrent();
	}

	/**
	 * A straight eastward traversal of the given length in tiles, built through the detector.
	 */
	private static Traversal traversal(int tiles)
	{
		TraversalDetector detector = new TraversalDetector();
		detector.onObjectClicked(ObjectID.WEREWOLF_SLIDE_CENTER, "Teeth-grip", 0);
		detector.onTick(PlayerSample.builder()
			.tick(1)
			.serverX(tiles * 128)
			.animation(1)
			.poseAnimation(-1)
			.idlePose(808)
			.build());
		return detector.getCurrent();
	}
}

package com.agilityactioncamera.rig;

import net.runelite.api.Perspective;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AnglesTest
{
	@Test
	public void jauRoundTrip()
	{
		for (int jau = 0; jau < Angles.JAU_PER_TURN; jau += 97)
		{
			assertEquals(jau, Angles.toJau(Angles.toRadians(jau)));
		}
		assertEquals(Angles.JAU_PER_TURN - 1024, Angles.toJau(-Math.PI / 8));
	}

	@Test
	public void wrapKeepsShortestTurn()
	{
		assertEquals(-Math.PI / 2, Angles.wrap(3 * Math.PI / 2), 1e-9);
		assertEquals(0.1, Angles.wrap(0.1 + 4 * Math.PI), 1e-9);
	}

	/**
	 * A point straight along the camera's forward vector must project to the
	 * screen centre in front of the camera, using the client's own rotation
	 * (Perspective.localToCanvas, JAU14 tables).
	 */
	@Test
	public void forwardMatchesClientProjection()
	{
		for (int jau = 0; jau < Angles.JAU_PER_TURN; jau += 512)
		{
			double yaw = Angles.toRadians(jau);
			int x = (int) Math.round(Angles.forwardX(yaw) * 1000);
			int y = (int) Math.round(Angles.forwardY(yaw) * 1000);

			int sin = Perspective.SINE14[jau];
			int cos = Perspective.COSINE14[jau];
			int screenX = x * cos + y * sin >> 16;
			int depth = y * cos - x * sin >> 16;

			assertTrue("centred at jau " + jau, Math.abs(screenX) <= 1);
			assertTrue("in front at jau " + jau, depth > 0);
		}
	}

	@Test
	public void yawLookingAlongInvertsForward()
	{
		double yaw = Angles.yawLookingAlong(0.6, -0.8);
		assertEquals(0.6, Angles.forwardX(yaw), 1e-9);
		assertEquals(-0.8, Angles.forwardY(yaw), 1e-9);
		// North is yaw 0
		assertEquals(0, Angles.yawLookingAlong(0, 1), 1e-9);
	}
}

package com.agilityactioncamera.rig;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CameraRigTest
{
	@Test
	public void springConvergesWithoutOvershoot()
	{
		Spring s = new Spring(0);
		double prev = 0;
		for (int i = 0; i < 300; i++)
		{
			double v = s.update(100, 6, 1 / 60.0);
			assertTrue("monotonic", v >= prev - 1e-9);
			assertTrue("no overshoot", v <= 100 + 1e-9);
			prev = v;
		}
		assertEquals(100, prev, 0.01);
	}

	@Test
	public void springIsFrameRateIndependent()
	{
		Spring fast = new Spring(0);
		Spring slow = new Spring(0);
		for (int i = 0; i < 144; i++)
		{
			fast.update(50, 5, 1 / 144.0);
		}
		for (int i = 0; i < 30; i++)
		{
			slow.update(50, 5, 1 / 30.0);
		}
		assertEquals(fast.get(), slow.get(), 1e-6);
	}

	@Test
	public void yawTurnsTheShortWayAcrossNorth()
	{
		CameraRig rig = new CameraRig();
		double nearlyFull = Angles.toRadians(16000);
		double justPast = Angles.toRadians(300);
		rig.snap(new CameraPose(0, 0, 0, nearlyFull, 0.5, 0.5));

		CameraPose p = rig.update(new CameraPose(0, 0, 0, justPast, 0.5, 0.5), 8, 0.05);
		// Moving forward from 16000 through 0 means the unwrapped yaw increases
		assertTrue(p.getYaw() > nearlyFull);
		for (int i = 0; i < 200; i++)
		{
			p = rig.update(new CameraPose(0, 0, 0, justPast, 0.5, 0.5), 8, 0.05);
		}
		assertEquals(0, Angles.wrap(p.getYaw() - justPast), 1e-3);
	}
}
